/* Host test of the headphone-surround kernel (xbox360/surround_dsp.h) with the generated table
 * (xbox360/surround_tab.h), one table size per build:
 *
 *   for t in 32 64 128; do
 *     cc -O2 -Wall -DXSR_TAPS=$t -o /tmp/test_surround tests/test_surround.c -lm &&
 *     /tmp/test_surround || break
 *   done
 *
 * Checks: bit-exact with the Python reference model (tools/hrtf/xsr_ref.py, vectors in
 * tools/hrtf/xsr_vectors.h, both regenerated by tools/hrtf/gen.py); a left-only input gives the
 * expected interaural level and time difference; front-left and surround-left differ in
 * spectrum; the output clamp counts as the model does and a mastered worst case never clamps;
 * stereo-only input comes out at the plain mix's level. Floating point is used here only to measure.
 */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include "../core/platform.h"
#include "../xbox360/surround_dsp.h"
#include "../xbox360/surround_tab.h"
#include "../tools/hrtf/xsr_vectors.h"

#define K_FRONT 6786 /* game_360.c's plain downmix (the OFF path), Q14 */
#define K_SIDE 4799
#define RATE 48000

static int g_fail;

static void check(int ok, const char *what)
{
	printf("%s %s\n", ok ? "PASS" : "FAIL", what);
	if (!ok)
		g_fail = 1;
}

static u32 xorshift(u32 *s)
{
	*s ^= *s << 13;
	*s ^= *s >> 17;
	*s ^= *s << 5;
	return *s;
}

static void noise16(u32 seed, s16 *out, int n)
{
	for (int i = 0; i < n; i++)
		out[i] = (s16)(xorshift(&seed) >> 16);
}

static s32 clamp16(s32 v)
{
	return v > 32767 ? 32767 : v < -32768 ? -32768 : v;
}

/* x: 6 planar channels of n frames. Runs the kernel in blocks (sizes from `blocks`, repeated)
 * from a fresh state; out: interleaved stereo. Returns the clamp count. */
static u32 run(s16 *const x[6], int n, const int *blocks, int nblocks, s16 *out)
{
	static struct xsr_state st;
	static s32 blk[6 * XSR_BLOCK];
	u32 clamps = 0;

	xsr_init(&st, &xsr_tab);
	for (int o = 0, b = 0; o < n; b++) {
		int m = blocks[b % nblocks];

		if (m > n - o)
			m = n - o;
		for (int c = 0; c < 6; c++)
			for (int i = 0; i < m; i++)
				blk[c * m + i] = x[c][o + i];
		clamps += xsr_process(&st, blk, (u32)m, out + 2 * o);
		o += m;
	}
	return clamps;
}

static const int FULL[] = { XSR_BLOCK };

/* the plain downmix of s16 input (the OFF path), interleaved */
static void downmix(s16 *const x[6], int n, s16 *out)
{
	for (int i = 0; i < n; i++) {
		out[2 * i] = (s16)clamp16((x[XSR_FL][i] * K_FRONT + (x[XSR_C][i] + x[XSR_SL][i]) * K_SIDE) >> 14);
		out[2 * i + 1] = (s16)clamp16((x[XSR_FR][i] * K_FRONT + (x[XSR_C][i] + x[XSR_SR][i]) * K_SIDE) >> 14);
	}
}

static s16 *chan[6];

static void clear(int n)
{
	for (int c = 0; c < 6; c++)
		memset(chan[c], 0, (size_t)n * sizeof(s16));
}

/* ILD (dB, left over right) and ITD (samples, right later) as gen.py's measure() reads them */
static void measure(const s16 *out, int n, double *ild, int *itd)
{
	double *l = malloc(sizeof(double) * n), *r = malloc(sizeof(double) * n);
	double el = 0, er = 0, best = -1e300;
	double xl[3] = { 0 }, yl[3] = { 0 }, xr[3] = { 0 }, yr[3] = { 0 };

	for (int i = 0; i < n; i++) {
		double a = out[2 * i], b = out[2 * i + 1];

		el += a * a;
		er += b * b;
		/* the 1.5 kHz low-pass, direct form I */
		xl[2] = xl[1], xl[1] = xl[0], xl[0] = a;
		yl[2] = yl[1], yl[1] = yl[0];
		yl[0] = xv_lp_b[0] * xl[0] + xv_lp_b[1] * xl[1] + xv_lp_b[2] * xl[2] -
			xv_lp_a[1] * yl[1] - xv_lp_a[2] * yl[2];
		xr[2] = xr[1], xr[1] = xr[0], xr[0] = b;
		yr[2] = yr[1], yr[1] = yr[0];
		yr[0] = xv_lp_b[0] * xr[0] + xv_lp_b[1] * xr[1] + xv_lp_b[2] * xr[2] -
			xv_lp_a[1] * yr[1] - xv_lp_a[2] * yr[2];
		l[i] = yl[0];
		r[i] = yr[0];
	}
	*ild = 10 * log10(el / er);
	for (int k = -48; k <= 48; k++) {
		double s = 0;

		for (int i = 48; i < n - 48; i++)
			s += l[i] * r[i + k];
		if (s > best) {
			best = s;
			*itd = k;
		}
	}
	free(l);
	free(r);
}

/* 1/3-octave band levels (dB) of one ear's impulse response, 200 Hz .. 16 kHz */
#define BANDS 20
static void bands(const s16 *out, int ear, int n, double *db)
{
	for (int b = 0; b < BANDS; b++) {
		double fc = 200 * pow(2, b / 3.0), p = 0;

		for (int j = 0; j < 8; j++) {
			double f = fc * pow(2, (j - 3.5) / 24.0), re = 0, im = 0;

			for (int i = 0; i < n; i++) {
				re += out[2 * i + ear] * cos(2 * M_PI * f * i / RATE);
				im -= out[2 * i + ear] * sin(2 * M_PI * f * i / RATE);
			}
			p += re * re + im * im;
		}
		db[b] = 10 * log10(p / 8 + 1e-9);
	}
}

static double power(const s16 *out, int n, int from)
{
	double s = 0;

	for (int i = 2 * from; i < 2 * n; i++)
		s += (double)out[i] * out[i];
	return s;
}

int main(void)
{
	enum { N = XV_MEAS_N };
	static const int VEC_BLOCKS[] = { 256, 255, 101, 256 }; /* odd sizes too */
	s16 *out = malloc(sizeof(s16) * 2 * N), *ref = malloc(sizeof(s16) * 2 * N);
	char msg[200];

	for (int c = 0; c < 6; c++)
		chan[c] = malloc(sizeof(s16) * N);
	printf("surround: %d taps, out_q14 %d, lfe_q14 %d, table %zu bytes, state %zu bytes\n",
	       XSR_TAPS, xsr_tab.out_q14, xsr_tab.lfe_q14, sizeof(xsr_tab), sizeof(struct xsr_state));
	check(xsr_table_ok(&xsr_tab) == XSR_OK, "table: magic, version, taps, rate, sum|h| <= 2.0, crc");
	{
		struct xsr_table bad = xsr_tab;

		bad.h[XSR_SURR_SUM][3] ^= 1;
		check(xsr_table_ok(&bad) == XSR_BAD_CRC, "table: a changed coefficient fails the crc");
		bad = xsr_tab;
		bad.h[XSR_CENTRE][0] = 32767;
		check(xsr_table_ok(&bad) == XSR_BAD_SUM, "table: sum|h| over 2.0 is refused");
	}

	/* 1. bit-exact with the reference model, in uneven blocks, with the extremes */
	{
		u32 cl, crc;
		int head = 1;

		clear(N);
		for (int c = 0; c < 6; c++) {
			noise16(XV_SEED + (u32)c * 0x9E3779B9u, chan[c], XV_N);
			for (int i = 0; i < 32; i++)
				chan[c][i] = c % 2 == 0 ? -32768 : 32767;
		}
		cl = run(chan, XV_N, VEC_BLOCKS, 4, out);
		crc = xsr_crc32(out, 2 * XV_N);
		for (int i = 0; i < 64; i++)
			head &= out[i] == xv_out_head[i];
		snprintf(msg, sizeof msg, "bit-exact with xsr_ref.py: crc %08x (want %08x), clamps %u (want %d)",
			 crc, XV_OUT_CRC, cl, XV_CLAMPS);
		check(head && crc == XV_OUT_CRC && cl == XV_CLAMPS, msg);

		downmix(chan, XSR_BLOCK, ref);
		xsr_crossfade(ref, ref, out, XSR_BLOCK);
		crc = xsr_crc32(ref, 2 * XSR_BLOCK);
		snprintf(msg, sizeof msg, "crossfade bit-exact: crc %08x (want %08x)", crc, XV_XFADE_CRC);
		check(crc == XV_XFADE_CRC, msg);
		check(ref[0] != out[0] && ref[2 * XSR_BLOCK - 1] == out[2 * XSR_BLOCK - 1] &&
			      ref[2 * XSR_BLOCK - 2] == out[2 * XSR_BLOCK - 2],
		      "crossfade starts at the old output and ends on the new");
	}

	/* 2. one speaker at a time: interaural level and time difference */
	{
		double ild_f, ild_s;
		int itd_f, itd_s;

		clear(N);
		noise16(XV_MEAS_SEED, chan[XSR_FL], N);
		for (int i = 0; i < N; i++)
			chan[XSR_FL][i] >>= 2;
		run(chan, N, FULL, 1, out);
		measure(out, N, &ild_f, &itd_f);
		memcpy(chan[XSR_SL], chan[XSR_FL], sizeof(s16) * N);
		memset(chan[XSR_FL], 0, sizeof(s16) * N);
		run(chan, N, FULL, 1, out);
		measure(out, N, &ild_s, &itd_s);
		snprintf(msg, sizeof msg,
			 "front-left: ILD %.2f dB (model %.2f), ITD %d samples = %.0f us (model %d)",
			 ild_f, XV_FL_ILD, itd_f, itd_f * 1e6 / RATE, XV_FL_ITD);
		check(fabs(ild_f - XV_FL_ILD) < 0.01 && itd_f == XV_FL_ITD, msg);
		snprintf(msg, sizeof msg,
			 "surround-left: ILD %.2f dB (model %.2f), ITD %d samples = %.0f us (model %d)",
			 ild_s, XV_SL_ILD, itd_s, itd_s * 1e6 / RATE, XV_SL_ITD);
		check(fabs(ild_s - XV_SL_ILD) < 0.01 && itd_s == XV_SL_ITD, msg);
		/* a real head: 30 degrees is 0.25-0.4 ms and louder on its own side; 110 degrees is
		 * further round, so later and more shadowed still */
		check(ild_f > 3 && itd_f >= 12 && itd_f <= 20, "front-left: the near ear is louder and earlier, by a 30-degree amount");
		check(ild_s > ild_f && itd_s > itd_f, "surround-left: more level and time difference than front-left");
	}

	/* 3. front-left and surround-left sound different (spectrum at the near ear) */
	{
		double a[BANDS], b[BANDS], ma = 0, mb = 0, worst = 0;

		clear(XSR_BLOCK);
		chan[XSR_FL][0] = 16384;
		run(chan, XSR_BLOCK, FULL, 1, out);
		bands(out, 0, XSR_BLOCK, a);
		clear(XSR_BLOCK);
		chan[XSR_SL][0] = 16384;
		run(chan, XSR_BLOCK, FULL, 1, out);
		bands(out, 0, XSR_BLOCK, b);
		for (int i = 0; i < BANDS; i++)
			ma += a[i] / BANDS, mb += b[i] / BANDS;
		for (int i = 0; i < BANDS; i++)
			if (fabs((a[i] - ma) - (b[i] - mb)) > worst)
				worst = fabs((a[i] - ma) - (b[i] - mb));
		snprintf(msg, sizeof msg,
			 "front-left vs surround-left, left ear: spectral shape differs by up to %.1f dB "
			 "(1/3 octave, 200 Hz-16 kHz, level removed)", worst);
		check(worst >= 3, msg);
	}

	/* 4. clipping. The table matches the plain mix's loudness, so white noise at full scale
	 * on all five main channels (no game produces it) clamps a little: the clamp is the
	 * protection, and it must count exactly as the model does. A mastered worst case (the
	 * same bright, low-heavy burst on all five channels, the plain mix at -0.1 dBFS) must
	 * not clamp at all. */
	{
		static const int MAIN[5] = { XSR_FL, XSR_FR, XSR_C, XSR_SL, XSR_SR };
		double y1 = 0, y2 = 0, x1 = 0, x2 = 0, top = 0;
		u32 cl, seed = 0xb00f;
		int peak = 0;

		clear(N);
		for (int k = 0; k < 5; k++)
			noise16(XV_FS_SEED + (u32)k, chan[MAIN[k]], N);
		cl = run(chan, N, FULL, 1, out);
		snprintf(msg, sizeof msg, "full-scale white noise on 5 channels: %u of %d samples "
			 "clamped (model %d), the clamp holds", cl, 2 * N, XV_FS_CLAMPS);
		check(cl == XV_FS_CLAMPS && cl < (u32)N / 100, msg);

		/* the burst: noise through the 1.5 kHz low-pass, decaying, the same on all five */
		clear(N);
		for (int i = 0; i < N; i++) {
			double w = (s32)xorshift(&seed) / 2147483648.0, y;

			y = xv_lp_b[0] * w + xv_lp_b[1] * x1 + xv_lp_b[2] * x2 - xv_lp_a[1] * y1 -
			    xv_lp_a[2] * y2;
			x2 = x1, x1 = w, y2 = y1, y1 = y;
			if (fabs(y * exp(-i / 9000.0)) > top)
				top = fabs(y * exp(-i / 9000.0));
		}
		seed = 0xb00f, x1 = x2 = y1 = y2 = 0;
		for (int i = 0; i < N; i++) {
			double w = (s32)xorshift(&seed) / 2147483648.0, y;

			y = xv_lp_b[0] * w + xv_lp_b[1] * x1 + xv_lp_b[2] * x2 - xv_lp_a[1] * y1 -
			    xv_lp_a[2] * y2;
			x2 = x1, x1 = w, y2 = y1, y1 = y;
			/* the plain mix of the same sample on every channel is that sample (the
			 * downmix weights sum to 1), so -0.1 dBFS on each channel */
			for (int k = 0; k < 5; k++)
				chan[MAIN[k]][i] = (s16)lrint(y * exp(-i / 9000.0) / top * 32767 * 0.98855);
		}
		cl = run(chan, N, FULL, 1, out);
		for (int i = 0; i < 2 * N; i++)
			peak = abs(out[i]) > peak ? abs(out[i]) : peak;
		snprintf(msg, sizeof msg, "the same burst on 5 channels, plain mix at -0.1 dBFS: %u "
			 "clamped, peak %.2f dBFS", cl, 20 * log10(peak / 32767.0));
		check(cl == 0, msg);
	}

	/* 5. stereo-only input (C, SL, SR, LFE silent): level against the plain downmix */
	{
		double b0[2] = { 0 }, b1[2] = { 0 }, b2[2] = { 0 }, on, off, d;
		u32 seed = 0x5eed;

		clear(N);
		for (int c = 0; c < 2; c++)
			for (int i = 0; i < N; i++) {
				/* pink noise (Kellet's economy filter), about -20 dBFS */
				double w = (s32)xorshift(&seed) / 2147483648.0;

				b0[c] = 0.99765 * b0[c] + w * 0.0990460;
				b1[c] = 0.96300 * b1[c] + w * 0.2965164;
				b2[c] = 0.57000 * b2[c] + w * 1.0526913;
				chan[c][i] = (s16)lrint((b0[c] + b1[c] + b2[c] + w * 0.1848) * 1200);
			}
		run(chan, N, FULL, 1, out);
		downmix(chan, N, ref);
		on = power(out, N, 4096);
		off = power(ref, N, 4096);
		d = 10 * log10(on / off);
		snprintf(msg, sizeof msg,
			 "stereo-only pink noise: ON %+.2f dB against the plain mix (the table's intent "
			 "%+.2f dB K-weighted)", d, XV_ONOFF_DB);
		check(fabs(d - XV_ONOFF_DB) < 1.0 && fabs(d) < 1.5, msg);
	}

	/* host speed, for information only (the console is a different machine) */
	{
		struct timespec t0, t1;
		static struct xsr_state st;
		static s32 blk[6 * XSR_BLOCK];
		int reps = 2000;

		noise16(1, out, 6 * XSR_BLOCK);
		for (int i = 0; i < 6 * XSR_BLOCK; i++)
			blk[i] = out[i];
		xsr_init(&st, &xsr_tab);
		clock_gettime(CLOCK_MONOTONIC, &t0);
		for (int i = 0; i < reps; i++)
			xsr_process(&st, blk, XSR_BLOCK, out);
		clock_gettime(CLOCK_MONOTONIC, &t1);
		printf("info host: %.1f us per 256-frame block (%d multiply-adds)\n",
		       ((t1.tv_sec - t0.tv_sec) * 1e9 + (t1.tv_nsec - t0.tv_nsec)) / 1e3 / reps,
		       5 * XSR_TAPS * XSR_BLOCK);
	}
	printf("%s\n", g_fail ? "FAILED" : "all passed");
	return g_fail;
}
